import '@/assets/css/mining_style.css'
import { CetusTooltip } from '@cetus/design'
import { cancelBubble } from '@cetus/utils'
import { Box, BoxProps, Center, HStack, Text } from '@chakra-ui/react'
import { useState } from 'react'
const MiningIcon = () => {
  return (
    <HStack
      w="16px"
      h="16px"
      onClick={e => {
        cancelBubble(e)
      }}
    >
      <CetusTooltip placement="top" tooltip={<Text fontSize="12px">Mining rewards available</Text>}>
        <Center>
          <MiningImage />
        </Center>
      </CetusTooltip>
    </HStack>
  )
}

const MiningImage = (props: BoxProps) => {
  const [active, setActive] = useState(false)
  const onMouseOver = () => {
    setActive(true)
  }
  const onMouseOut = () => {
    setActive(false)
  }
  return (
    <Box as="div" w="20px" h="20px" pos="relative" cursor="pointer" onMouseEnter={onMouseOver} onMouseLeave={onMouseOut} {...props}>
      <Box as="div" className="mining_composition">
        <Box as="div" className={`mining_class3 mining_bg3 ${active ? 'mining_ani3' : ''} `} />
        <Box as="div" className={`mining_class2 mining_bg2 ${active ? 'mining_ani2' : ''} `} />
        <Box as="div" className={`mining_class1 mining_bg1 ${active ? 'mining_ani1' : ''} `} />
      </Box>
    </Box>
  )
}

export default MiningIcon

export { MiningImage }
